export const ERROR_KIND_META_KEY = 'mcpsignals/error_kind';

export interface ToolCallEvent {
  event_type: 'tool_call';
  ts: Date;
  server_name: string;
  server_version: string | null;
  tool_name: string;
  session_id: string | null;
  agent_id: string | null;
  client_name: string | null;
