201	  /**
202	   * What the tool callback saw, handed from the `registerTool` wrapper to the
203	   * `tools/call` recorder below. Keyed by the request's `ctx`: McpServer
204	   * passes its `tools/call` handler's `ctx` straight through to the tool
205	   * callback, so both layers see the same object.
206	   */
207	  const handlerCalls = new WeakMap<object, IntentFields>();
208	  /** Registered tool name -> whether intent capture injected its schema. */
209	  const registeredTools = new Map<string, boolean>();
210	
211	  const originalRegisterTool = server.registerTool.bind(server);
212	
213	  server.registerTool = ((
214	    name: string,
215	    config: Record<string, unknown>,
216	    cb: (...args: unknown[]) => unknown
217	  ) => {
218	    const intentEnabled = isIntentCaptureEnabled(options.intentCapture, name);
219	    const originalInputSchema = config.inputSchema;
220	    const canInject = intentEnabled && schemaSupportsInjection(originalInputSchema);
221	    registeredTools.set(name, canInject);
222	
223	    const wrappedConfig = canInject
224	      ? { ...config, inputSchema: injectIntentSchema(originalInputSchema) }
225	      : config;
226	
227	    /** Strips injected intent-capture keys and leaves them for the recorder. */
228	    const prepare = (args: Record<string, unknown>, ctx: ToolCallContext) => {
229	      const fields = canInject ? extractIntentFields(args) : noIntentFields(args);
230	      handlerCalls.set(ctx, fields);
231	      return fields.clean;
232	    };
233	
