5	 * (the spec's named exception to the `_meta` key-prefix rule).
6	 *
7	 * The client controls this value, so anything that is not exactly the
8	 * format is dropped rather than recorded: a version of `ff`, an all-zero id,
9	 * or a version-00 header with trailing fields. A higher version may append
10	 * fields; only the first four are read, as the W3C spec requires.
11	 */
12	export function parseTraceparent(value: unknown): { traceId: string; parentSpanId: string } | null {
13	  if (typeof value !== 'string') return null;
14	  const match = /^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-[0-9a-f]{2}(-.*)?$/.exec(value);
15	  if (!match) return null;
16	  const [, version, traceId, parentSpanId, rest] = match;
17	  if (version === 'ff' || (version === '00' && rest !== undefined)) return null;
18	  if (/^0+$/.test(traceId) || /^0+$/.test(parentSpanId)) return null;
19	  return { traceId, parentSpanId };
20	}

